// Parity of the .rep XML reader and of the hydration with the C# engine: every fixture of
// test/fixtures/cases.json (generated by test/generate-fixtures.mjs with golden-cs model-json) is
// read with readReportXml and hydrated with hydrateReport, and the result is compared with the
// JSON C# gives for the same file.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import {
  BarcodeItem,
  ChartItem,
  ChangeObjectOperation,
  ChangeOperationItem,
  DataInfo,
  DatabaseInfo,
  ExpressionItem,
  ImageItem,
  LabelItem,
  Param,
  Report,
  Section,
  ShapeItem,
  SubReport,
  UndoCue,
  hydrateReport,
  readReportXml,
  serializeReport,
} from "@reportman/lib";
import { Comparison, compare, isNil } from "./model-compare.js";

const packageDir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
interface Case {
  id: string;
  rep: string;
  json?: string;
  error?: string;
}
const cases: Case[] = JSON.parse(fs.readFileSync(path.join(packageDir, "test/fixtures/cases.json"), "utf8"));
const readJson = (rel: string) => JSON.parse(fs.readFileSync(path.join(packageDir, rel), "utf8"));
const readBytes = (rel: string) => new Uint8Array(fs.readFileSync(path.join(packageDir, rel)));

function checkInstances(report: Report): void {
  expect(report).toBeInstanceOf(Report);
  for (const d of report.databaseInfo) expect(d).toBeInstanceOf(DatabaseInfo);
  for (const d of report.dataInfo) expect(d).toBeInstanceOf(DataInfo);
  for (const p of report.params) expect(p).toBeInstanceOf(Param);
  const classes: Record<string, unknown> = {
    TRPLABEL: LabelItem,
    TRPEXPRESSION: ExpressionItem,
    TRPSHAPE: ShapeItem,
    TRPIMAGE: ImageItem,
    TRPBARCODE: BarcodeItem,
    TRPCHART: ChartItem,
  };
  for (const s of report.subReports) {
    expect(s).toBeInstanceOf(SubReport);
    for (const sec of s.sections) {
      expect(sec).toBeInstanceOf(Section);
      for (const comp of sec.components) expect(comp).toBeInstanceOf(classes[comp.className as string] as any);
    }
  }
  if (report.undoCue) {
    expect(report.undoCue).toBeInstanceOf(UndoCue);
    for (const op of [...report.undoCue.undoOperations, ...report.undoCue.redoOperations]) {
      expect(op).toBeInstanceOf(ChangeObjectOperation);
      expect(op.date).toBeInstanceOf(Date);
      for (const prop of op.properties) expect(prop).toBeInstanceOf(ChangeOperationItem);
    }
  }
  // The component list holds every named item by uppercase name.
  for (const [key, item] of report.components) expect(key).toBe(item.name.toUpperCase());
}

/** The names of every item of a C# report JSON, in the order the component list is built. */
function allNames(cs: any): string[] {
  const names: string[] = [];
  for (const d of cs.databaseInfo ?? []) names.push(d.name);
  for (const d of cs.dataInfo ?? []) names.push(d.name);
  for (const p of cs.params ?? []) names.push(p.name);
  for (const s of cs.subReports ?? []) {
    names.push(s.name);
    for (const sec of s.sections ?? []) {
      names.push(sec.name);
      for (const c of sec.components ?? []) names.push(c.name);
    }
  }
  return names;
}

const jsonCases = cases.filter((c) => c.json);

describe("readReportXml gives the design properties of the C# reader", () => {
  it("has the fixtures", () => {
    expect(jsonCases.length).toBeGreaterThanOrEqual(17 + 5);
  });
  for (const c of jsonCases) {
    it(c.id, () => {
      const cs = readJson(c.json!);
      const report = readReportXml(readBytes(c.rep));
      checkInstances(report);
      const ts = serializeReport(report);
      const out: Comparison = { diffs: [], compared: 0 };
      compare("report", cs, ts, "report", out, true);
      expect(out.diffs).toEqual([]);
      expect(out.compared).toBeGreaterThan(50);
      // The undo history comes from BINCUE, as in C#.
      expect(isNil(report.undoCue)).toBe(isNil(cs.undoCue));
    });
  }
});

describe("hydrateReport keeps the C# JSON", () => {
  for (const c of jsonCases) {
    it(c.id, () => {
      const cs = readJson(c.json!);
      const report = hydrateReport(cs);
      checkInstances(report);
      expect(report.undoCue).toBeInstanceOf(UndoCue);
      const ts = serializeReport(report);
      const out: Comparison = { diffs: [], compared: 0 };
      compare("report", cs, ts, "report", out, false);
      // hydrateReport gives a new name to a repeated one (the designer addresses items by name);
      // the engine keeps both.
      const names = allNames(cs).map((n) => n.toUpperCase());
      const repeated = new Set(names.filter((n, i) => names.indexOf(n) !== i));
      const renamed = (d: string) => {
        const m = /\.name: C# "([^"]*)" TS "([^"]*)"$/.exec(d);
        return m !== null && repeated.has(m[1].toUpperCase()) && /^TRP[A-Z]+\d+$/.test(m[2]);
      };
      expect(out.diffs.filter((d) => !renamed(d))).toEqual([]);
    });
  }
});

describe("the C# reader errors", () => {
  for (const c of cases.filter((c) => c.error)) {
    it(c.id, () => {
      const expected = readJson(c.error!);
      let message: string | undefined;
      try {
        readReportXml(readBytes(c.rep));
      } catch (e) {
        message = (e as Error).message;
      }
      expect(message).toBe(expected.message);
    });
  }
});
